const b = $input.first().json.body || $input.first().json;
if (!b.project_no || !Array.isArray(b.rows)) throw new Error('缺少 project_no 或 rows 数组');
return [{ json: b }];

const out = [];
for (const it of $input.all()) {
  const ai = it.json.choices?.[0]?.message?.content || it.json.content || '';
  let p;
  try { p = JSON.parse(String(ai).replace(/^```json?|```$/g, '').trim()); }
  catch (e) { throw new Error('AI检查输出解析失败：' + String(ai).slice(0, 300)); }
  const src = $('校验输入').first().json;
  const problems = p.problems || [];
  let md = '### 报价检查报告 ' + src.project_no + '\n';
  md += problems.length ? problems.map(x => `- **[${x.type}]** ${x.location}：${x.issue}\n  建议：${x.suggestion}`).join('\n') : '全部检查通过。';
  out.push({ json: { ...src, problems, report_md: md, has_problems: problems.length > 0, ai_summary: p.summary } });
}
return out;

const out = [];
for (const it of $input.all()) {
  const ai = it.json.choices?.[0]?.message?.content || it.json.content || '';
  const d = $('解析检查结果').first().json;
  out.push({ json: { ...d, quote_note: String(ai).trim(), version_no: d.project_no + '-' + (d.version || 'Q01') } });
}
return out;
